package com.hmdp.ai.infrastructure.dify;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.hmdp.ai.domain.external.DifyWorkflowGateway;import com.hmdp.ai.infrastructure.external.*;import com.hmdp.ai.infrastructure.model.*;import org.springframework.stereotype.Component;import java.net.URI;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
@Component public class HttpDifyWorkflowGateway implements DifyWorkflowGateway {private final SafeHttpClient http;private final SecretResolutionService secrets;private final ObjectMapper mapper;public HttpDifyWorkflowGateway(SafeHttpClient http,SecretResolutionService secrets,ObjectMapper mapper){this.http=http;this.secrets=secrets;this.mapper=mapper;}public JsonNode run(JsonNode config,JsonNode input,String user,String runId,int timeoutMs){try{DifyAppConfiguration c=new DifyAppConfiguration(config);ObjectNode body=mapper.createObjectNode();body.set("inputs",input);body.put("response_mode",c.getResponseMode());body.put("user",user);body.put("run_id",runId);Map<String,String>headers=new LinkedHashMap<>();headers.put("Authorization","Bearer "+secrets.resolve(c.getSecretRef()));headers.put("Content-Type","application/json");headers.put("Accept",c.getResponseMode().equals("streaming")?"text/event-stream":"application/json");Set<String>types=new LinkedHashSet<>(Arrays.asList("application/json","text/event-stream"));OutboundHttpResponse response=http.execute(new OutboundHttpRequest(new URI(c.getScheme(),null,c.getHost(),c.getPort(),c.getPath(),null,null),"POST",headers,mapper.writeValueAsBytes(body),Duration.ofMillis(timeoutMs),c.getMaxResponseBytes(),types,c.isAllowPrivate()));if(response.getStatusCode()<200||response.getStatusCode()>=300)throw new IllegalStateException("DIFY_STATUS_"+response.getStatusCode());return response.getContentType().equals("text/event-stream")?parseStream(response.bodyAsUtf8()):mapper.readTree(response.getBody());}catch(SecretNotConfiguredException e){throw new IllegalArgumentException("DIFY_PROVIDER_NOT_CONFIGURED",e);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalStateException("DIFY_EXECUTION_FAILED",e);}}
    private JsonNode parseStream(String value)throws Exception{ArrayNode events=mapper.createArrayNode();JsonNode output=NullNode.instance;for(String line:value.split("\\R")){if(!line.startsWith("data:"))continue;JsonNode event=mapper.readTree(line.substring(5).trim());events.add(event);if("workflow_finished".equals(event.path("event").asText()))output=event.path("data").path("outputs");}ObjectNode result=mapper.createObjectNode();result.set("events",events);result.set("outputs",output);return result;}}
